import itertools
def cells(P,k):
    return [(r,c) for r in range(4) for c in range(4) if P[k][r][c]!=0]

def predict_nb(P, rad, agg):
    pts={k:cells(P,k) for k in range(4)}
    out=[]
    for r in range(4):
        orow=[]
        for c in range(4):
            cov=[k for k in range(4) if P[k][r][c]!=0]
            if not cov: orow.append(0);continue
            if agg=='max3':  # count in 3x3
                key=lambda k: sum(abs(pr-r)<=1 and abs(pc-c)<=1 for pr,pc in pts[k])
            elif agg=='max5':
                key=lambda k: sum(abs(pr-r)<=2 and abs(pc-c)<=2 for pr,pc in pts[k])
            elif agg=='minmax3':
                key=lambda k: -sum(abs(pr-r)<=1 and abs(pc-c)<=1 for pr,pc in pts[k])
            elif agg=='dist':
                key=lambda k: min(abs(pr-r)+abs(pc-c) for pr,pc in pts[k])
            vals=[key(k) for k in cov]
            best=min(vals)
            cand=[k for k in cov if key(k)==best]
            cand.sort(key=lambda k:-k)
            orow.append(cand[0])
        out.append(orow)
    return out
